    { ...{"id":"step-2","title":"连接菜单与标签","goal":"在 Provider 内调用标签 Hook，将菜单事件映射为 openTab。","why":"布局负责导航与标签容器，Provider 保存已打开的页面。","instruction":"点击成员管理，再切回概览。","expected":"新标签显示成员页面，原概览仍可返回。","changes":["在 Provider 内调用标签 Hook，将菜单事件映射为 openTab。"],"sourceCode":"import { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport AppMainLayout, {\n    AppMainLayoutProvider,\n    useAppMainLayoutTabs,\n} from \"@crab-dev/rc-app-main-layout\";\nimport { MenuItemType } from \"@crab-dev/rc-menu\";\nimport \"@crab-dev/rc-app-main-layout/css/index.css\";\nimport \"@crab-dev/rc-menu/css/index.css\";\nconst frame = css`\n    height: calc(${token.space[\"section-gap\"]} * 30);\n    min-width: 0;\n    overflow: hidden;\n`;\nconst loadMenus = async () => [\n    {\n        key: \"members\",\n        title: \"成员管理\",\n        type: MenuItemType.Item,\n    },\n];\nfunction Workspace() {\n    const { openTab } = useAppMainLayoutTabs();\n    return (\n        <AppMainLayout\n            sidebarTitle=\"项目工作区\"\n            sidebarLoadMenus={loadMenus}\n            fullscreenable={false}\n            onSidebarMenuItemClick={() =>\n                openTab({\n                    key: \"members\",\n                    title: \"成员管理\",\n                    children: <p>林晓 · 周宁</p>,\n                    closable: true,\n                })\n            }\n        />\n    );\n}\nexport default function Example() {\n    return (\n        <div className={frame}>\n            <AppMainLayoutProvider\n                initialTabs={[\n                    {\n                        key: \"home\",\n                        title: \"概览\",\n                        children: <p>欢迎进入项目工作区。</p>,\n                    },\n                ]}\n                initialActiveTabKey=\"home\"\n            >\n                <Workspace />\n            </AppMainLayoutProvider>\n        </div>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-app-main-layout/step-2.js") } }
